    agent = Mock(spec=Agent)
    agent.agent_id = "agent1"
    agent.state = AgentState()
    agent._internal_state = {"key": "value"}
    session_manager._last_synced_internal_state[agent.agent_id] = {"key": "value"}
    update_agent_mock = Mock(wraps=session_manager.session_repository.update_agent)
