    class State:
        def __init__(self):
            self._dirty = True
        def _is_dirty(self):
            return self._dirty
        def _clear_dirty(self):
            self._dirty = False
    agent.state = State()
    agent._internal_state = {"key": "value"}
    session_manager._last_synced_internal_state[agent.agent_id] = {"key": "value"}
